```java
public static boolean isThreePower(int n) {
    if (n < 0 || n > 2147483647) { // Check input range
        throw new IllegalArgumentException("Input must be between -231 and 231 - 1");
    }
    int x = 0;
    while (3 * (int) Math.pow(3, x) <= n) {
