```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string wordToSearch; // Wort, das gesucht werden soll
    int count = 0; // Anzahl der Vorkommen des Wortes

    // Wort, das gesucht werden soll, vom Benutzer einlesen
    cout << "Bitte das zu suchende Wort eingeben: ";
    cin >> wordToSearch;

    // Dateiname vom Benutzer einlesen
