    // Fehlerbehandlung bei Dateiöffnung
    if (!file) {
        cerr << "Fehler: Datei konnte nicht geöffnet werden!" << endl;
        return 1;
    }

    // Zeile für Zeile lesen und Wort zählen
    string line;
    while (getline(file, line)) {
        size_t pos = 0;
        while ((pos = line.find(wordToSearch, pos)) != string::npos) {
            count++; // Wort gefunden, Anzahl erhöhen
            pos += wordToSearch.length(); // nächste Suche beginnen nach dem gefundenen Wort
